p-read-a-json-body-with-a-size-limit.starter:
import type { IncomingMessage } from 'node:http';

/** Read the request body as JSON. Throw new HttpError(415, ...) unless Content-Type is application/json or
 *  application/*+json, HttpError(413, ...) as soon as the body passes limitBytes (check Content-Length first,
 *  and stop reading), and HttpError(400, ...) for malformed JSON. */
async function readJson(req: IncomingMessage, limitBytes: number): Promise<unknown> {
  throw new Error('Not implemented');
}

p-read-a-json-body-with-a-size-limit.solution:
import type { IncomingMessage } from 'node:http';
async function readJson(req: IncomingMessage, limitBytes: number): Promise<unknown> {
  const type = req.headers['content-type'] ?? '';
  if (!/^application\/(?:[\w.+-]+\+)?json\b/i.test(type)) throw new HttpError(415, 'Expected application/json');
  const declared = Number(req.headers['content-length']);
  if (Number.isFinite(declared) && declared > limitBytes) throw new HttpError(413, 'Payload too large');
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > limitBytes) throw new HttpError(413, 'Payload too large');
    chunks.push(chunk as Buffer);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw new HttpError(400, 'Malformed JSON');
  }
}

