p-validation-middleware-with-zod-and-pro.starter:
import type { RequestHandler } from 'express';

import { z } from 'zod';

/** Parse req.body with schema. On success replace req.body with the parsed data and call next(); on failure
 *  answer 422 application/problem+json with errors: [{ path: 'a.b', message }]. */
function validateBody(schema: z.ZodType): RequestHandler {
  throw new Error('Not implemented');
}

p-validation-middleware-with-zod-and-pro.solution:
import type { RequestHandler } from 'express';
import { z } from 'zod';
function validateBody(schema: z.ZodType): RequestHandler {
  return (req, res, next) => {
    const result = schema.safeParse(req.body ?? {});
    if (result.success) {
      req.body = result.data;
      return next();
    }
    res
      .status(422)
      .type('application/problem+json')
      .json({
        type: 'about:blank',
        title: 'Invalid request body',
        status: 422,
        errors: result.error.issues.map((i) => ({ path: i.path.join('.'), message: i.message })),
      });
  };
}

