import { AsyncLocalStorage } from 'node:async_hooks';

/** Push { severity: 'INFO', message, requestId, ...fields } to sink, with the requestId of the request that
 *  is running (none outside a request). */
const logger = {
  info(message: string, fields: Record<string, unknown> = {}): void {
    throw new Error('Not implemented');
  },
};

/** Run fn so that everything it does, across awaits, logs with this requestId. */
function withRequestContext<T>(requestId: string, fn: () => Promise<T>): Promise<T> {
  throw new Error('Not implemented');
}

p-request-scoped-context-for-logs.solution:
import { AsyncLocalStorage } from 'node:async_hooks';
const storage = new AsyncLocalStorage<{ requestId: string }>();
const logger = {
  info(message: string, fields: Record<string, unknown> = {}) {
    sink.push({ severity: 'INFO', message, ...storage.getStore(), ...fields });
  },
};
function withRequestContext<T>(requestId: string, fn: () => Promise<T>): Promise<T> {
  return storage.run({ requestId }, fn);
}

